{"edits":[{"path":"openclaw_runtime/src/agents/rate-circuit-breaker.ts","content":"export type RateCircuitBreakerState = "closed" | "open" | "half-open";

export interface RateCircuitBreakerOptions {
  /** Number of failures required to open the circuit. */
  failureThreshold: number;
  /** Length of the sliding failure window, in milliseconds. */
  windowMs: number;
  /** Time that the circuit remains open before a probe is allowed. */
  cooldownMs: number;
  /** Injectable clock used by tests and deterministic replay. */
  clock?: () => number;
}

export class RateCircuitOpenError extends Error {
  readonly code = "RATE_CIRCUIT_OPEN";

  constructor() {
    super("rate circuit breaker is open");
    this.name = "RateCircuitOpenError";
  }
}

/**
 * A small, deterministic circuit breaker for abnormal call rates.
 *
 * The breaker is deliberately a boundary in front of an operation: an open
 * circuit rejects work before the operation is invoked. It does not inspect,
 * weaken, or replace any SSRF, approval, budget, or loop-guard checks.
 */
export class RateCircuitBreaker {
  private currentState: RateCircuitBreakerState = "closed";
  private readonly failureTimes: number[] = [];
  private openedAt = 0;
  private probeInFlight = false;
  private readonly clock: () => number;

  constructor(private readonly options: RateCircuitBreakerOptions) {
    if (!Number.isFinite(options.failureThreshold) || options.failureThreshold < 1) {
      throw new RangeError("failureThreshold must be a positive number");
    }
    if (!Number.isFinite(options.windowMs) || options.windowMs <= 0) {
      throw new RangeError("windowMs must be a positive number");
    }
    if (!Number.isFinite(options.cooldownMs) || options.cooldownMs < 0) {
      throw new RangeError("cooldownMs must be a non-negative number");
    }
    this.clock = options.clock ?? (() => Date.now());
  }

  get state(): RateCircuitBreakerState {
    this.refreshState();
    return this.currentState;
  }

  /** Alias useful to callers that prefer an explicit state read. */
  getState(): RateCircuitBreakerState {
    return this.state;
  }

  /**
   * Returns whether a request may proceed. In half-open, reserving the probe
   * is part of this operation, so two calls cannot both be admitted.
   */
  allowRequest(): boolean {
    this.refreshState();
    if (this.currentState === "open") {
      return false;
    }
    if (this.currentState === "half-open") {
      if (this.probeInFlight) {
        return false;
      }
      this.probeInFlight = true;
    }
    return true;
  }

  /** Alias for allowRequest. */
  beforeRequest(): boolean {
    return this.allowRequest();
  }

  /** Records a successful call and closes a successful half-open probe. */
  recordSuccess(): void {
    this.refreshState();
    if (this.currentState === "half-open") {
      this.probeInFlight = false;
      this.currentState = "closed";
    }
    if (this.currentState === "closed") {
      this.failureTimes.length = 0;
    }
  }

  /** Alias for recordSuccess. */
  onSuccess(): void {
    this.recordSuccess();
  }

  /** Records a failed call. */
  recordFailure(): void {
    const now = this.clock();
    this.refreshState(now);

    if (this.currentState === "half-open") {
      this.probeInFlight = false;
      this.open(now);
      return;
    }

    if (this.currentState === "open") {
      return;
    }

    const cutoff = now - this.options.windowMs;
    while (this.failureTimes.length > 0 && this.failureTimes[0] <= cutoff) {
      this.failureTimes.shift();
    }
    this.failureTimes.push(now);
    if (this.failureTimes.length >= this.options.failureThreshold) {
      this.open(now);
    }
  }

  /** Alias for recordFailure. */
  onFailure(): void {
    this.recordFailure();
  }

  /**
   * Runs an operation only when the breaker admits it. The operation is not
   * invoked while open, and errors are reported to the breaker before being
   * rethrown.
   */
  async execute<T>(operation: () => T | Promise<T>): Promise<T> {
    if (!this.allowRequest()) {
      throw new RateCircuitOpenError();
    }
    try {
      const result = await operation();
      this.recordSuccess();
      return result;
    } catch (error) {
      this.recordFailure();
      throw error;
    }
  }

  private refreshState(now = this.clock()): void {
    if (this.currentState !== "open") {
      return;
    }
    if (now - this.openedAt >= this.options.cooldownMs) {
      this.currentState = "half-open";
      this.probeInFlight = false;
    }
  }

  private open(now: number): void {
    this.currentState = "open";
    this.openedAt = now;
    this.probeInFlight = false;
  }
}

export function createRateCircuitBreaker(options: RateCircuitBreakerOptions): RateCircuitBreaker {
  return new RateCircuitBreaker(options);
}

/** Functional form for callers that do not need to retain an instance. */
export function checkRateCircuitBreaker(
  breaker: RateCircuitBreaker,
  operation: () => unknown | Promise<unknown>,
): Promise<unknown> {
  return breaker.execute(operation);
}
